import type { Severity } from './types.js';

export interface SiteFinding {
  id: string;
  severity: Severity;
  message: string;
}

export interface SiteReport {
  url: string;
  findings: SiteFinding[];
  // What did not answer, or answered only in part. Nothing was concluded from it.
  notChecked: string[];
}

interface Page {
  status: number;
  url: string;
  headers: Headers;
  body: string;
  truncated: boolean;
}

type Attrs = Record<string, string>;

const TIMEOUT_MS = 15_000;
const MAX_BODY = 2_000_000;
const MAX_ASSETS = 3;

const PLATFORM_HOSTS = [
  'vercel.app', 'netlify.app', 'lovable.app', 'lovableproject.com', 'pages.dev', 'onrender.com',
  'web.app', 'firebaseapp.com', 'replit.app', 'repl.co', 'herokuapp.com', 'up.railway.app',
  'github.io', 'surge.sh', 'glitch.me',
];
const TEMPLATE_TITLE = /^(react app|vite app|vite \+ (react|vue|svelte|preact|lit|solid)( \+ ts)?|create next app)$/i;
const TEMPLATE_DESCRIPTION = /^(generated by create next app|web site created using create-react-app|lovable generated project)$/i;
const BUILDER_BADGE = /\b(made|built|edit|created)\s+(with|in|on|by)\s+(lovable|bolt|v0|replit|base44)\b/i;
const BUILDER_SCRIPT = /gpteng\.co|lovable\.(dev|app)/i;
// ponytail: Tailwind gradient stop classes only; a hand-written linear-gradient() in purple hex is not detected.
const PURPLE_STOP = /\b(from|via|to)-(purple|violet|indigo|fuchsia)-\d{2,3}\b/;
const GOOGLE_FONTS = /fonts\.(googleapis|gstatic)\.com/i;
const SESSION_REPLAY: Array<[RegExp, string]> = [
  [/hotjar\.com/i, 'Hotjar'], [/fullstory\.com/i, 'FullStory'], [/logrocket\.(com|io)/i, 'LogRocket'],
  [/clarity\.ms/i, 'Microsoft Clarity'], [/smartlook\.com/i, 'Smartlook'], [/mouseflow\.com/i, 'Mouseflow'],
];
const ENV_LINE = /^\s*(export\s+)?[A-Za-z_][A-Za-z0-9_.]*\s*=/m;
const GIT_HEAD = /^(ref: refs\/|[0-9a-f]{40}([0-9a-f]{24})?\s*$)/;
const ROBOTS_DIRECTIVE = /^\s*(user-agent|disallow|allow|sitemap)\s*:/im;
// The document itself is a sitemap: optional XML declaration, processing instructions or comments, then the root.
const SITEMAP_DOC = /^﻿?\s*(<\?[\s\S]*?\?>\s*|<!--[\s\S]*?-->\s*)*<(urlset|sitemapindex)\b/i;
// An app root left empty for JavaScript to fill: React, Vue, Next, Nuxt, Svelte, Angular.
const EMPTY_MOUNT = /<div\b[^>]*\bid=["']?(root|app|__next|__nuxt|svelte)(?=["'\s>])[^>]*>\s*<\/div>|<app-root\b[^>]*>\s*<\/app-root>/i;

async function fetchPage(url: string): Promise<Page> {
  const res = await fetch(url, {
    headers: { 'user-agent': 'vibecheck-site (+https://github.com/yuvrajangadsingh/vibecheck)' },
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  const reader = res.body?.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  let truncated = false;
  while (reader) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    size += value.length;
    if (size >= MAX_BODY) {
      truncated = true;
      await reader.cancel();
      break;
    }
  }
  // ponytail: charset from the Content-Type header only; a page that declares it in <meta> decodes as UTF-8.
  const label = /charset=["']?([\w-]+)/i.exec(res.headers.get('content-type') ?? '')?.[1] ?? 'utf-8';
  let decoder: TextDecoder;
  try {
    decoder = new TextDecoder(label);
  } catch {
    decoder = new TextDecoder(); // unknown label: UTF-8 is the web default
  }
  return { status: res.status, url: res.url, headers: res.headers, body: decoder.decode(Buffer.concat(chunks)), truncated };
}

function reason(err: unknown): string {
  const cause = (err as { cause?: { code?: string } }).cause;
  if (cause?.code) return cause.code;
  return err instanceof Error ? err.message : String(err);
}

const contentType = (p: Page) => p.headers.get('content-type') ?? '';
const isHtml = (p: Page) => /text\/html/i.test(contentType(p)) || /^\s*</.test(p.body);

function tags(markup: string, name: string): Attrs[] {
  return [...markup.matchAll(new RegExp(`<${name}\\b([^>]*)>`, 'gi'))].map((m) => {
    const attrs: Attrs = {};
    for (const a of m[1].matchAll(/([^\s=/]+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g)) {
      attrs[a[1].toLowerCase()] = (a[2] ?? a[3] ?? a[4] ?? '').replace(/&amp;/g, '&');
    }
    return attrs;
  });
}

// True when every crawler is told to stay out: a * group exists and no group lets anything through.
export function robotsBlocksAll(robots: string): boolean {
  const groups: Array<{ agents: string[]; rules: string[] }> = [];
  let inAgents = false;
  for (const raw of robots.split(/\r?\n/)) {
    const m = raw.replace(/#.*/, '').trim().match(/^([a-z-]+)\s*:\s*(.*)$/i);
    if (!m) continue;
    const key = m[1].toLowerCase();
    if (key === 'user-agent') {
      if (!inAgents) groups.push({ agents: [], rules: [] });
      inAgents = true;
      groups[groups.length - 1].agents.push(m[2].trim());
    } else {
      inAgents = false;
      groups[groups.length - 1]?.rules.push(`${key}:${m[2].replace(/\s/g, '')}`);
    }
  }
  // Groups naming the same crawler merge into one rule set (RFC 9309, 2.2.1).
  const byAgent = new Map<string, string[]>();
  for (const g of groups) {
    for (const agent of g.agents) byAgent.set(agent.toLowerCase(), [...(byAgent.get(agent.toLowerCase()) ?? []), ...g.rules]);
  }
  const blocks = (rules: string[]) =>
    rules.some((r) => r === 'disallow:/' || r === 'disallow:/*') && !rules.some((r) => r.startsWith('allow:') && r !== 'allow:');
  return byAgent.has('*') && [...byAgent.values()].every(blocks);
}

const isChallenge = (p: Page) =>
  p.headers.get('cf-mitigated') === 'challenge' || p.headers.get('x-amzn-waf-action') === 'challenge';

interface Evidence {
  base: URL;
  page: Page;
  html: string;
  markup: string;
  text: string;
  jsOnly: boolean;
  links: Attrs[];
  scripts: Attrs[];
  iconHref: string | undefined;
  missingPath: string;
  plainHttp: Page | null;
  missing: Page | null;
  robots: Page | null;
  sitemap: Page | null;
  favicons: Array<Page | null>;
  env: Page | null;
  gitHead: Page | null;
  maps: string[];
  css: Array<Page | null>;
}

async function gather(input: string, notChecked: string[]): Promise<Evidence> {
  const start = /^https?:\/\//i.test(input) ? input : `https://${input}`;
  let page: Page;
  try {
    page = await fetchPage(start);
  } catch (err) {
    throw new Error(`could not fetch ${start}: ${reason(err)}`);
  }
  if (page.status >= 400) throw new Error(`${start} returned ${page.status}`);
  if (isChallenge(page)) throw new Error(`${start} answered with a bot challenge, so there is nothing to check`);

  const base = new URL(page.url);
  if (page.truncated) notChecked.push(`${base.href} past the first 2 MB`);
  const probe = async (url: string): Promise<Page | null> => {
    try {
      const p = await fetchPage(url);
      // A rate limit, a server error or a bot challenge says nothing about the file asked for.
      if (p.status === 429 || p.status >= 500 || isChallenge(p)) {
        notChecked.push(`${url} (${p.status})`);
        return null;
      }
      if (p.truncated) notChecked.push(`${url} past the first 2 MB`);
      return p;
    } catch (err) {
      notChecked.push(`${url} (${reason(err)})`);
      return null;
    }
  };
  const at = (path: string) => new URL(path, base.origin).href;

  const html = page.body.replace(/<!--[\s\S]*?-->/g, ' ');
  // Tags are read from markup with script, style and template bodies emptied, so a "<link>" inside a string is not one.
  const markup = html.replace(/(<(script|style|template)\b[^>]*>)[\s\S]*?(<\/\2\s*>)/gi, '$1$3');
  const { links, scripts, scriptUrls, cssUrls, iconHref, iconUrls } = assets(markup, base);
  const text = html
    .replace(/<head\b[\s\S]*?<\/head\s*>/gi, ' ')
    .replace(/<(script|style|noscript|template|svg)\b[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const missingPath = `/vibecheck-404-${Math.random().toString(36).slice(2, 10)}`;
  const [plainHttp, missing, robots, sitemap, favicons, env, gitHead, jsFiles, css] = await Promise.all([
    base.protocol === 'https:' ? probe(`http://${base.host}/`) : Promise.resolve(null),
    probe(at(missingPath)),
    probe(at('/robots.txt')),
    probe(at('/sitemap.xml')),
    Promise.all(iconUrls.map((u) => probe(u))),
    probe(at('/.env')),
    probe(at('/.git/HEAD')),
    Promise.all(scriptUrls.map((u) => probe(u))),
    Promise.all(cssUrls.map((u) => probe(u))),
  ]);
  const maps = await exposedMaps(scriptUrls, jsFiles, probe);

  return {
    base, page, html, markup, text, links, scripts, iconHref, missingPath,
    jsOnly: scripts.length > 0 && (text.length === 0 || (text.length < 80 && EMPTY_MOUNT.test(markup))),
    plainHttp, missing, robots, sitemap, favicons, env, gitHead, maps, css,
  };
}

// The URLs a browser would fetch for this page, resolved against <base href> like a browser does.
function assets(markup: string, base: URL) {
  const links = tags(markup, 'link');
  const scripts = tags(markup, 'script');
  let docBase = base;
  try {
    docBase = new URL(tags(markup, 'base')[0]?.href ?? '', base);
  } catch {
    // a malformed <base href> is ignored by browsers too
  }
  const sameOrigin = (href: string | undefined) => {
    if (!href) return null;
    try {
      const u = new URL(href, docBase);
      return u.origin === base.origin ? u.href : null;
    } catch {
      return null;
    }
  };
  const scriptUrls = scripts.map((s) => sameOrigin(s.src)).filter((u): u is string => !!u).slice(0, MAX_ASSETS);
  const cssUrls = links
    .filter((l) => /\bstylesheet\b/i.test(l.rel ?? ''))
    .map((l) => sameOrigin(l.href))
    .filter((u): u is string => !!u)
    .slice(0, MAX_ASSETS);
  // rel="icon" or "shortcut icon"; apple-touch-icon and mask-icon are not the tab icon.
  const iconHrefs = links.filter((l) => (l.rel ?? '').toLowerCase().split(/\s+/).includes('icon') && l.href).map((l) => l.href);
  // An inline data: icon needs no fetch; with no usable link, browsers try /favicon.ico.
  const resolved = iconHrefs.flatMap((h) => {
    try {
      return [new URL(h, docBase).href];
    } catch {
      return [];
    }
  });
  const iconUrls = iconHrefs.some((h) => h.startsWith('data:')) ? []
    : (resolved.length ? resolved : [new URL('/favicon.ico', base.origin).href]).slice(0, MAX_ASSETS);
  return { links, scripts, scriptUrls, cssUrls, iconHref: iconHrefs[0], iconUrls };
}

// A script names its map in a SourceMap header or a trailing sourceMappingURL comment; without either, try <script>.map.
async function exposedMaps(urls: string[], files: Array<Page | null>, probe: (url: string) => Promise<Page | null>): Promise<string[]> {
  const found = await Promise.all(urls.map(async (url, i) => {
    const js = files[i];
    const ref = js?.headers.get('sourcemap') ?? js?.headers.get('x-sourcemap')
      ?? [...(js?.body ?? '').matchAll(/[#@]\s*sourceMappingURL=([^\s*'"]+)/g)].pop()?.[1];
    if (ref?.startsWith('data:')) return `${new URL(url).pathname} (inline)`;
    let mapUrl = `${url.split(/[?#]/)[0]}.map`;
    try {
      if (ref) mapUrl = new URL(ref, url).href;
    } catch {
      return null; // a malformed map URL points nowhere, for browsers too
    }
    const map = await probe(mapUrl);
    return map?.status === 200 && !isHtml(map) && /"(mappings|sources)"\s*:/.test(map.body) ? new URL(map.url).pathname : null;
  }));
  return found.filter((m): m is string => !!m);
}

// Things a stranger can download right now, and the transport around them.
function securityFindings(ev: Evidence): SiteFinding[] {
  const out: SiteFinding[] = [];
  const add = (severity: Severity, id: string, message: string) => out.push({ id, severity, message });
  if (ev.env?.status === 200 && !/^\s*</.test(ev.env.body) && ENV_LINE.test(ev.env.body)) {
    add('error', 'exposed-env', '/.env is publicly readable');
  }
  if (ev.gitHead?.status === 200 && GIT_HEAD.test(ev.gitHead.body)) {
    add('error', 'exposed-git', '/.git/ is publicly readable, so the source and its history can be downloaded');
  }
  if (ev.maps.length) add('warn', 'exposed-source-map', `source maps are public: ${ev.maps.join(', ')}`);

  const { base, page } = ev;
  if (base.protocol === 'http:') {
    add('warn', 'no-https', 'the page is served over plain http');
  } else if (ev.plainHttp && ev.plainHttp.status < 400 && new URL(ev.plainHttp.url).protocol === 'http:') {
    add('warn', 'http-not-redirected', `http://${base.host}/ serves the site over plain http instead of redirecting to https`);
  }
  if (base.protocol === 'https:' && !page.headers.get('strict-transport-security')) {
    add('warn', 'missing-hsts', 'no Strict-Transport-Security header');
  }
  if (!page.headers.get('content-security-policy')) add('info', 'missing-csp', 'no Content-Security-Policy header');
  if (page.headers.get('x-content-type-options')?.toLowerCase() !== 'nosniff') {
    add('info', 'missing-nosniff', 'no X-Content-Type-Options: nosniff header');
  }
  return out;
}

// The defaults a generator leaves behind, plus the legal flags (flag, don't advise).
// A probe that did not answer (null) concludes nothing here; it is already in notChecked.
function pageFindings(ev: Evidence): SiteFinding[] {
  const out: SiteFinding[] = [];
  const add = (severity: Severity, id: string, message: string) => out.push({ id, severity, message });
  const { base, html, markup, text, links, scripts } = ev;

  const platform = PLATFORM_HOSTS.find((h) => base.hostname === h || base.hostname.endsWith(`.${h}`));
  if (platform) add('warn', 'platform-domain', `served from a ${platform} subdomain, not your own domain`);
  // Only a 200 at the made-up URL itself: a redirect to a login or home page is a different answer.
  if (ev.missing?.status === 200 && new URL(ev.missing.url).pathname.replace(/\/$/, '') === ev.missingPath) {
    add('warn', 'soft-404', `${ev.missingPath} returns 200, so there is no real 404 page`);
  }
  if (ev.jsOnly) {
    add('warn', 'js-only-page', 'the HTML has no visible text until JavaScript runs, so crawlers and link previews see an empty page');
  }

  const title = markup.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i)?.[1].trim() ?? '';
  const meta = (key: string) =>
    tags(markup, 'meta').find((t) => t.name?.toLowerCase() === key || t.property?.toLowerCase() === key)?.content?.trim();
  const description = meta('description');
  if (!title) add('warn', 'missing-title', 'no <title>');
  else if (TEMPLATE_TITLE.test(title)) add('warn', 'template-title', `the title is the starter template's default: "${title}"`);
  if (!description) add('warn', 'missing-description', 'no meta description');
  else if (TEMPLATE_DESCRIPTION.test(description)) {
    add('warn', 'template-description', `the meta description is the starter template's default: "${description}"`);
  }
  if (!meta('og:image')) add('warn', 'missing-og-image', 'no og:image, so shared links show no preview image');
  if (!links.some((l) => /\bcanonical\b/i.test(l.rel ?? ''))) add('info', 'missing-canonical', 'no canonical link');
  if (!tags(markup, 'html')[0]?.lang) add('info', 'missing-lang', '<html> has no lang attribute');
  // An icon loads when it is a non-empty image, not the app shell; one failed probe leaves it unknown.
  const iconLoads = (p: Page) => p.status === 200 && p.body.length > 0 && /^(image\/|application\/octet-stream)/i.test(contentType(p))
    && !/^\s*<(!doctype|html)\b/i.test(p.body);
  const icons = ev.favicons.filter((p): p is Page => p !== null);
  if (icons.length && icons.length === ev.favicons.length && !icons.some(iconLoads)) {
    add('warn', 'no-favicon', ev.iconHref ? `the favicon ${ev.iconHref} does not load` : 'no favicon link and no /favicon.ico');
  }

  const r = ev.robots;
  const robotsFile = r && r.status === 200 && !isHtml(r) && (r.body.replace(/#.*/g, '').trim() === '' || ROBOTS_DIRECTIVE.test(r.body));
  const robots = robotsFile && r ? r.body : null;
  if (r && robots === null) add('info', 'no-robots', 'no /robots.txt');
  if (robots !== null && robotsBlocksAll(robots)) {
    add('warn', 'robots-blocks-all', 'robots.txt disallows / for every crawler, so search engines cannot crawl the site');
  }
  const s = ev.sitemap;
  const sitemapOk = (s?.status === 200 && SITEMAP_DOC.test(s.body)) || /^\s*sitemap\s*:/im.test(robots ?? '');
  if (!sitemapOk && s && r) add('info', 'no-sitemap', 'no /sitemap.xml and no Sitemap line in robots.txt');

  const badge = text.match(BUILDER_BADGE)?.[0];
  if (badge || scripts.some((sc) => BUILDER_SCRIPT.test(sc.src ?? '')) || /lovable/i.test(meta('author') ?? '')) {
    add('warn', 'builder-badge', badge ? `the page says "${badge}"` : 'the page loads an AI site-builder script or credit');
  }
  const css = ev.css.filter((c): c is Page => c?.status === 200).map((c) => c.body);
  const purple = [html, ...css].join('\n').match(PURPLE_STOP)?.[0];
  if (purple) add('info', 'purple-gradient', `purple gradient classes (${purple}), the default AI-site look`);
  if (!ev.jsOnly) {
    const dashes = (text.match(/—|&mdash;|&#8212;|&#x2014;/gi) ?? []).length;
    if (dashes >= 3) add('info', 'em-dashes', `${dashes} em dashes in the page copy`);
    const anchors = markup.match(/<a\b[^>]*>[\s\S]*?<\/a>/gi) ?? [];
    // A page cut at 2 MB may have its footer links past the cut.
    if (!ev.page.truncated && !anchors.some((a) => /privacy/i.test(a))) add('info', 'no-privacy-link', 'no link to a privacy policy');
  }

  // Loaded means a <link> to Google, or an @import or url() in a stylesheet, not a mention in the copy.
  const inlineCss = (html.match(/<style\b[^>]*>[\s\S]*?<\/style\s*>/gi) ?? []).join('\n');
  if (links.some((l) => GOOGLE_FONTS.test(l.href ?? '')) || GOOGLE_FONTS.test([inlineCss, ...css].join('\n'))) {
    add('info', 'google-fonts', "fonts load from Google's servers, which sends each visitor's IP to Google (an EU privacy issue); self-host them");
  }
  // Script code that runs: JSON-LD and framework data blocks only mention URLs.
  const scriptCode = (html.match(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi) ?? [])
    .filter((b) => !/^<script\b[^>]*\btype=["']?application\/(ld\+)?json/i.test(b))
    .join('\n');
  const replay = SESSION_REPLAY.filter(([re]) => re.test(scriptCode)).map(([, name]) => name);
  if (replay.length) add('info', 'session-replay', `session recording (${replay.join(', ')}): the privacy policy has to say so`);
  return out;
}

export async function auditSite(input: string): Promise<SiteReport> {
  const notChecked: string[] = [];
  const ev = await gather(input, notChecked);
  const order: Record<Severity, number> = { error: 0, warn: 1, info: 2 };
  const findings = [...securityFindings(ev), ...pageFindings(ev)].sort((a, b) => order[a.severity] - order[b.severity]);
  return { url: ev.base.href, findings, notChecked };
}
